mapper.select:
SELECT a.*, 
       s.student_no, s.name as student_name, c.class_name,
       co.course_name
FROM attendance a
LEFT JOIN student s ON a.student_id = s.student_no
LEFT JOIN class c ON s.class_id = c.class_code
LEFT JOIN course_arrangement ca ON a.course_arrangement_id = ca.id
LEFT JOIN course co ON ca.course_code = co.course_code


        AND a.student_id = #{studentId}


        AND ca.teacher_no = #{teacherNo}


        AND a.course_arrangement_id = #{courseArrangementId}


        AND a.attendance_date = #{attendanceDate}


        AND a.status = #{status}


ORDER BY a.attendance_date DESC, a.create_time DESC

SELECT COUNT(*) FROM attendance
WHERE student_id = #{studentId}
  AND status = #{status}
  AND attendance_date BETWEEN #{startDate} AND #{endDate}
